import json, sys
baseline = json.load(open('baseline-packages.json'))
after = json.load(sys.stdin)

def pkg_map(data):
    result = {}
    for proj in data['projects']:
        name = proj['path'].split('/')[-1]
        for fw in proj['frameworks']:
            for pkg in fw['topLevelPackages']:
                key = (name, fw['framework'], pkg['id'])
                result[key] = pkg['resolvedVersion']
    return result

b = pkg_map(baseline)
a = pkg_map(after)

changes = []
unchanged = []
for key in sorted(set(list(b.keys()) + list(a.keys()))):
    proj, fw, pkg = key
    bv = b.get(key, '-')
    av = a.get(key, '-')
    if bv != av:
        changes.append((proj, fw, pkg, bv, av))
    else:
        unchanged.append((proj, fw, pkg, av))

print('=== CHANGES ===')
for c in changes:
    print(f'{c[0]} ({c[1]}): {c[2]} {c[3]} -> {c[4]}')
print()
print(f'=== UNCHANGED: {len(unchanged)} packages ===')"

